js=r'''
// Distinct map tasks, authentic learning return, sources and voluntary card actions.
state.wellness.continuity.cardActions=Array.isArray(state.wellness.continuity.cardActions)?state.wellness.continuity.cardActions:[];
function journeyLife(){const notes=Object.keys(state.wellness.intentions).filter(d=>d<=today()).sort().reverse(),latest=notes.length?state.wellness.intentions[notes[0]]:null,theme=latest?.intention||latest?.direction||latest?.relation||'';return `<section class="page px-map-page j-life" data-map="life">${pxTop(t('Life map','生命地图'),t('A personal archive that grows with you','一份慢慢展开的个人探索档案'))}<div class="px-map-hero j-life-intro"><span class="px-kicker">${t('EXPLORE YOUR OWN STORY','从自己的故事开始')}</span><h2>${state.daily.traits?t('Your exploration is taking shape','你的探索，正在积累'):t('Which part of yourself would you like to know?','你想先了解自己的哪一面？')}</h2><p>${theme?esc(theme).slice(0,130):t('Start with a real question from daily life.','从生活里一个真实在意的问题开始。')}</p></div><div class="j-archive-line"><span>${state.daily.traits?t('Strengths observed','已有特质观察'):t('Strengths not recorded','特质观察尚未记录')}</span><span>${notes.length} ${t('reflection days','天生活觉察')}</span></div><div class="px-grid">${pxTile('spark',t('My strengths','天赋特质'),t('Observe your own tendencies','认识自己的倾向'),'traits')}${pxTile('compass',t('Life themes','人生课题'),t('Choose what matters now','选一个当下在意的问题'),'lifeThemes')}${pxTile('chart',t('Zi Wei culture','紫微命盘'),t('Explore traditional symbols','了解传统文化符号'),'ziweiChart')}${pxTile('book',t('Culture & notes','文化与记录'),t('Read, reflect and revisit','阅读、觉察与回看'),'ziweiCulture')}</div><section class="j-life-notes"><h3>${t('Return to my own words','回到我自己的文字')}</h3><p>${notes.length?t('Your reflections remain available to revisit.','已有的生活觉察可随时回看，不必每次从头开始。'):t('Begin with a small reflection. No conclusion about your destiny is required.','可以先留下一条生活觉察，不急着给人生下结论。')}</p>${go(t('Open my exploration notes','打开我的探索记录'),'lifeReview','secondary full')}</section><div class="ew-map-flow" aria-label="${t('Reflect, practice and revisit','觉察、实践与回看')}">${[[t('Strengths','觉察当下'),'traits'],[t('Life theme','开始实践'),'lifeThemes'],[t('My notes','回看记录'),'lifeReview']].map(([label,to],i)=>`<button data-action="go" data-to="${to}"><span>0${i+1}</span>${label}${icon('arrow')}</button>`).join('')}</div>${pxDeviceRow('life')}</section>`;}
function journeyMind(){const entry=state.wellness.mind[today()];return `<section class="page px-map-page j-mind" data-map="mind">${pxTop(t('Mind map','心智地图'),t('Begin with a breath or a feeling','先从一次呼吸，或一种感受开始'))}<div class="px-map-hero j-mind-intro"><span class="px-kicker">${entry?t('TODAY’S FEELING','今天记录的感受'):t('A MOMENT TO SETTLE','给此刻一个停顿')}</span><h2>${entry?moodName(entry.mood):t('You can begin right here.','现在，就可以开始。')}</h2><p>${entry?.note?esc(entry.note).slice(0,120):t('No preparation needed. Choose a comfortable position.','不必先读完一篇介绍，找一个舒适的姿势就好。')}</p></div><div class="j-mind-actions"><button class="btn full" data-action="journey-start" data-practice="breath">${icon('play')}${t('Begin one quiet minute','开始一分钟静心')}</button>${go(entry?t('Update how I feel','更新此刻感受'):t('Record how I feel','记下此刻感受'),'emotionAwareness','secondary full')}</div><div class="px-grid">${pxTile('lotus',t('Meditation','禅修静心'),t('Choose a length','选择适合的时长'),'zenPractice')}${pxTile('heart',t('Emotional notes','情绪觉察'),t('A place for your own words','留给自己的文字'),'emotionAwareness')}${pxTile('book',t('Learning','修习课程'),t('Learn when you want to go deeper','想深入时，再了解'),'buddhistCourses')}${pxTile('clock',t('Daily rhythm','每日安排'),t('Leave a little room in the day','为日常留一个空隙'),'timeline')}</div><div class="ew-map-flow" aria-label="${t('Reflect, practice and revisit','觉察、实践与回看')}">${[[t('Reflect','觉察当下'),'emotionAwareness'],[t('Practice','开始实践'),'zenPractice'],[t('Revisit','回看记录'),'mindHistory']].map(([label,to],i)=>`<button data-action="go" data-to="${to}"><span>0${i+1}</span>${label}${icon('arrow')}</button>`).join('')}</div>${pxDeviceRow('mind')}</section>`;}
const journeyAcademyOpenBefore=academyOpen;academyOpen=function(id){const course=academyCatalog.find(x=>x.id===id);if(course){state.wellness.continuity.learning={id,at:new Date().toISOString()};persist();}return journeyAcademyOpenBefore(id);};
function journeyAcademy(){const last=state.wellness.continuity.learning,course=last&&academyCatalog.find(x=>x.id===last.id),visible=course&&(!px.loaded||(px.content.courses||[]).some(x=>x.id===course.id));let source=academyHome().replace('class="page academy-page ew-learning-page"',`class="page academy-page ew-learning-page j-learning-page ${visible?'has-return':''}"`);const resume=visible?`<section class="j-learning-return"><span class="j-label">${t('LAST OPENED ON THIS DEVICE','上次在本机查看')}</span><h2>${esc(t(course.en||course.zh,course.zh))}</h2><p>${esc(t(course.summaryEn||course.summaryZh||'',course.summaryZh||''))}</p><button class="btn secondary full" data-action="academy-open" data-id="${esc(course.id)}">${t('Continue exploring','继续了解这份内容')}${icon('arrow')}</button></section>`:'';return source.replace('<div class="ew-learning-intro">',resume+'<div class="ew-learning-intro">').replace('让理解，<br>在生活里发生。','从需要出发，<br>把理解带进日常。');}
function journeyCourse(){const item=academyCurrent(),source=pxCourseDetail(),refs=(item.sources||[]).filter(x=>Array.isArray(x)&&x.length===2&&x.every(v=>typeof v==='string')&&/^https:\/\//.test(x[1]));const panel=`<section class="j-content-sources"><h3>${t('Reference sources','内容参考出处')}</h3>${refs.length?`<ul>${refs.map(([name,url])=>`<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)}</a></li>`).join('')}</ul>`:`<p>${t('Reference details have not been supplied for this item.','这份内容的参考出处资料待补充。')}</p>`}<p class="small">${t('A reference link does not establish course authorization. Formal teacher and licensing details need to be supplied separately.','参考链接不代表正式课程授权，老师及授权资料需按实际发布内容提供。')}</p></section>`;const at=source.lastIndexOf('</section>');return source.slice(0,at)+panel+source.slice(at);}
function journeyCurrentCard(){const date=state.cardDate||today(),draw=state.daily.draws[date];return draw?{date,card:draw.snapshot||dailyCards.find(c=>c.id===draw.cardId)}:null;}
function journeyCard(){let source=pxCardPage();const current=journeyCurrentCard();if(!current?.card?.actionZh)return source;const id=current.date+'|'+current.card.id,joined=state.wellness.continuity.cardActions.some(x=>x.id===id);const button=`<div class="j-card-action"><button class="btn secondary full" data-action="journey2-card-plan" ${joined?'disabled':''}>${joined?t('Added to my day','已加入今日安排'):t('Add this small action to my day','把这个小行动加入今日安排')}</button>${joined?go(t('Open my daily rhythm','查看每日安排'),'timeline','link'):''}</div>`;return source.replace('<div class="px-reading">',button+'<div class="px-reading">');}
function journeyTimeline(){const source=v3Timeline(),actions=state.wellness.continuity.cardActions.filter(x=>x.date===(state.selectedDate||today()));if(!actions.length)return source;const extra=`<section class="j-card-plan"><h2>${t('Small actions I chose','我自愿留下的小行动')}</h2>${actions.map(a=>`<article><span class="j-label">${t('FROM A REFLECTION CARD','来自每日智慧卡片')}</span><h3>${esc(a.title)}</h3><p>${esc(t(a.actionEn||a.action,a.action))}</p><button class="btn secondary" data-action="journey2-card-done" data-id="${esc(a.id)}" ${a.doneAt?'disabled':''}>${a.doneAt?t('I marked this as done','我已标记完成'):t('Mark when I have done it','做到后，记下一次完成')}</button></article>`).join('')}<p class="px-note">${t('Self-reported completion, without a practice-time claim.','这是自己标记的小行动，不计为自动测得的练习时长。')}</p></section>`;const at=source.lastIndexOf('</section>');return source.slice(0,at)+extra+source.slice(at);}
const journeyEventsBefore=growthEvents;growthEvents=function(){return [...journeyEventsBefore(),...state.wellness.continuity.cardActions.filter(x=>x.doneAt).map(x=>({kind:'cardAction',date:x.date,title:t('A small action, done','完成了一个卡片小行动'),copy:t(x.actionEn||x.action,x.action),symbol:'check'}))].sort((a,b)=>b.date.localeCompare(a.date));};
function journeyChat(){const r=journeyRecommendation();const action=`<details class="j-ai-next"><summary>${t('A practical next step using my records','根据我的记录，先做一件小事')}</summary><p>${t('Local rule-based suggestion, not an AI response.','本机规则匹配建议，不是AI生成的回复。')}</p><p>${esc(r.reason)}</p><button class="btn secondary full" data-action="journey-start" data-practice="${r.key}">${practiceName(r.key)}</button></details>`;return pxChat().replace('<p class="ew-compose-note">',action+'<p class="ew-compose-note">');}
Object.assign(screens,{lifeResult:journeyLife,mind:journeyMind,academy:journeyAcademy,academyDetail:journeyCourse,dailyCard:journeyCard,timeline:journeyTimeline,service:journeyChat,serviceChat:journeyChat});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||!el.dataset.action.startsWith('journey2-'))return;e.preventDefault();e.stopImmediatePropagation();if(el.dataset.action==='journey2-card-plan'){const current=journeyCurrentCard();if(!current?.card?.actionZh)return;const id=current.date+'|'+current.card.id;if(!state.wellness.continuity.cardActions.some(x=>x.id===id))state.wellness.continuity.cardActions.push({id,date:current.date,cardId:current.card.id,title:current.card.zh,action:current.card.actionZh,actionEn:current.card.actionEn||'',createdAt:new Date().toISOString(),doneAt:null});persist();render(false);toast(t('Added to your chosen day.','小行动已加入对应日期的安排。'));}else if(el.dataset.action==='journey2-card-done'){const action=state.wellness.continuity.cardActions.find(x=>x.id===el.dataset.id);if(action&&!action.doneAt){action.doneAt=new Date().toISOString();persist();render(false);}}},true);
render(false);
'''
